function cartKey(){return 'jowwa-test-cart:'+app.actor+':'+app.shopId+':'+(app.tab==='cash'?'pos':'customer');}
function loadCart(){try{const rows=JSON.parse(sessionStorage.getItem(cartKey())||'[]');app.cart=Array.isArray(rows)?rows.filter(x=>app.raw.products[x.productId]?.shopId===app.shopId&&Number.isInteger(x.quantity)&&x.quantity>0).slice(0,40):[];}catch{app.cart=[];}}
