function defaultTab(){if(app.model.roles.includes('admin'))return 'approvals';if(app.model.roles.some(r=>['courier','driver'].includes(r)))return 'missions';if(app.model.shops.some(x=>x.canOrders))return 'orders';return 'shops';}
